import { TypeInfo } from '../metadata/dwarf-types';

/**
 * Symbol fallback for Watch, hover, and Debug Console expressions.
 *
 * The typed C evaluator resolves identifiers through DWARF variables and
 * registers. Assembler labels and constants — including the offset constants
 * generated by `.struct` — are ELF symbols instead, so the adapter consults
 * the debug index for them:
 *
 * - Bare identifiers fall back inside the frame resolver (`resolve()`).
 * - Dotted expressions such as `char.health` parse as member access, so every
 *   dotted token with exactly one symbol-table match is substituted with its
 *   numeric value before parsing. Typed member expressions like `hero.pos_x`
 *   are not symbols and pass through unchanged.
 * - A symbol in a real section is an addressable object: it evaluates as live
 *   memory at its address (like a C variable). An SHN_ABS constant evaluates
 *   as its own numeric value (like a C enum constant). `*(char*)CONST` reads
 *   the RAM at an address held by a constant.
 */

/** Bare identifier or dotted assembler symbol, e.g. `hero`, `char.health`. */
export const SYMBOL_NAME_PATTERN = /^[A-Za-z_.@][A-Za-z0-9_.@$]*$/;

/** Dotted token inside a larger expression, e.g. `char.health` in `char.health + 2`. */
export const DOTTED_SYMBOL_PATTERN = /\b[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)+\b/g;

/** How a uniquely matched ELF symbol evaluates in an expression. */
export type SymbolValue =
    | { kind: 'constant'; value: number }
    | { kind: 'memory'; address: number; byteSize: number };

/**
 * Classify a unique symbol match: absolute constants carry their value, real
 * section symbols address memory (size-bounded; untyped labels read one byte).
 */
export function uniqueSymbolValue(
    symbols: ReadonlyArray<{ address: number; size: number; absolute?: boolean }>,
): SymbolValue | undefined {
    if (symbols.length !== 1) { return undefined; }
    const symbol = symbols[0];
    if (symbol.absolute) { return { kind: 'constant', value: symbol.address }; }
    return { kind: 'memory', address: symbol.address, byteSize: Math.max(1, Math.min(symbol.size || 1, 4)) };
}

/**
 * Replace every dotted token that resolves to exactly one symbol address with
 * its hexadecimal literal; unknown tokens (typed member paths) are preserved.
 */
export function substituteKnownSymbols(
    expression: string,
    lookup: (name: string) => number | undefined,
): string {
    return expression.replace(DOTTED_SYMBOL_PATTERN, token => {
        const value = lookup(token);
        return value === undefined ? token : `0x${value.toString(16)}`;
    });
}

// ---------------------------------------------------------------------------
// Builtin primitive types for cast expressions in pure-assembler sessions
// ---------------------------------------------------------------------------

const BUILTIN_BASE_TYPES: ReadonlyArray<{ name: string; byteSize: number; signed: boolean }> = [
    { name: 'void', byteSize: 0, signed: false },
    { name: 'char', byteSize: 1, signed: false },
    { name: 'signed char', byteSize: 1, signed: true },
    { name: 'unsigned char', byteSize: 1, signed: false },
    { name: 'short', byteSize: 2, signed: true },
    { name: 'unsigned short', byteSize: 2, signed: false },
    { name: 'int', byteSize: 2, signed: true },
    { name: 'unsigned int', byteSize: 2, signed: false },
    { name: 'long', byteSize: 4, signed: true },
    { name: 'unsigned long', byteSize: 4, signed: false },
];

const builtinTypes = (() => {
    const byName = new Map<string, TypeInfo>();
    for (const [index, base] of BUILTIN_BASE_TYPES.entries()) {
        const type: TypeInfo = { id: -(index + 1), kind: 'base', ...base };
        if (base.byteSize > 0) {
            byName.set(`${base.name} *`, { id: -(100 + index), kind: 'pointer', name: `${base.name} *`, byteSize: 2, signed: false, of: type, targetByteSize: base.byteSize });
        }
        byName.set(base.name, type);
    }
    return byName;
})();

/** Builtin primitive or pointer-to-primitive type for cast expressions. */
export function builtinTypeInfo(name: string): TypeInfo | undefined {
    return builtinTypes.get(name);
}

/** Display type for a live-memory label value. */
export function labelTypeInfo(byteSize: number): TypeInfo {
    return { id: -200, kind: 'base', name: 'asm', byteSize, signed: false };
}